#include <stdio.h>
#include <string.h>

#define V 5

int g[V][V];
int color[V];      /* 0=白(未访问) 1=灰(在递归栈中) 2=黑(已完成) */
int hasCycle;

void dfs(int u) {
    color[u] = 1;
    printf("  进入 %d（灰）\n", u);
    for (int v = 0; v < V; v++) {
        if (!g[u][v]) continue;
        if (color[v] == 0) {
            dfs(v);
        } else if (color[v] == 1) {
            printf("  发现回边 %d -> %d：%d 仍在递归栈中 => 有环\n", u, v, v);
            hasCycle = 1;
        }
    }
    color[u] = 2;
    printf("  完成 %d（黑）\n", u);
}

void run(const char *name, int edges[][2], int m) {
    memset(g, 0, sizeof(g));
    memset(color, 0, sizeof(color));
    hasCycle = 0;
    for (int i = 0; i < m; i++) g[edges[i][0]][edges[i][1]] = 1;

    printf("=== %s ===\n", name);
    for (int u = 0; u < V; u++)
        if (color[u] == 0) dfs(u);
    printf("结论：%s\n\n", hasCycle ? "存在环，不是 DAG，无法拓扑排序" : "无环，是 DAG，可拓扑排序");
}

int main(void) {
    /* 情形一：DAG（无环） */
    int dag[][2] = {{0,1},{0,2},{1,3},{2,3},{3,4}};
    run("情形一：DAG 0->1,0->2,1->3,2->3,3->4", dag, 5);

    /* 情形二：含环 0->1->2->0 */
    int cyc[][2] = {{0,1},{1,2},{2,0},{3,4}};
    run("情形二：含环 0->1->2->0, 3->4", cyc, 4);

    printf("要点：bool visited 无法区分「递归栈上的祖先（灰）」与「已完成的兄弟分支（黑）」，\n");
    printf("      会把 DAG 误判为有环。判有向图环必须用三色标记。\n");
    return 0;
}
